using System.IO;using System.Windows;using System.Windows.Input;using ViewportCap.Core;using MessageBox=System.Windows.MessageBox;
namespace ViewportCap.App.Windows;
public partial class SettingsWindow:Window
{
 private readonly AppSettings _settings;private readonly ISettingsStore _store;private readonly Func<HotkeyGesture,bool> _hotkeyTester;private readonly Action<AppSettings> _saved;
 public SettingsWindow(AppSettings settings,ISettingsStore store,Func<HotkeyGesture,bool> hotkeyTester,Action<AppSettings> onSaved){InitializeComponent();_settings=settings;_store=store;_hotkeyTester=hotkeyTester;_saved=onSaved;HotkeyBox.Text=settings.Hotkey;OutputFolderBox.Text=settings.OutputFolder;CountdownBox.ItemsSource=new[]{0,3,5,10};CountdownBox.SelectedItem=settings.CountdownSeconds;FormatBox.ItemsSource=Enum.GetValues<OutputFormat>();FormatBox.SelectedItem=settings.DefaultFormat;AudioModeBox.ItemsSource=Enum.GetValues<AudioMode>();AudioModeBox.SelectedItem=settings.AudioMode;StartWithWindowsBox.IsChecked=settings.StartWithWindows;VersionText.Text=$"Version {typeof(SettingsWindow).Assembly.GetName().Version?.ToString(3)??"0.1.0"}";}
 private void HotkeyBox_PreviewKeyDown(object sender,System.Windows.Input.KeyEventArgs e){e.Handled=true;var key=e.Key==Key.System?e.SystemKey:e.Key;var mods=HotkeyModifiers.None;if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control))mods|=HotkeyModifiers.Control;if(Keyboard.Modifiers.HasFlag(ModifierKeys.Alt))mods|=HotkeyModifiers.Alt;if(Keyboard.Modifiers.HasFlag(ModifierKeys.Shift))mods|=HotkeyModifiers.Shift;var gesture=new HotkeyGesture(mods,(uint)KeyInterop.VirtualKeyFromKey(key));if(HotkeyGesture.TryParse(gesture.ToString(),out _))HotkeyBox.Text=gesture.ToString();}
 private void Browse_Click(object sender,RoutedEventArgs e){using var d=new System.Windows.Forms.FolderBrowserDialog{SelectedPath=OutputFolderBox.Text};if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)OutputFolderBox.Text=d.SelectedPath;}
 private void Save_Click(object sender,RoutedEventArgs e){if(!HotkeyGesture.TryParse(HotkeyBox.Text,out var hotkey)||!_hotkeyTester(hotkey)||string.IsNullOrWhiteSpace(OutputFolderBox.Text)){MessageBox.Show("Enter a valid, available hotkey and output folder.","viewport-cap");return;}var updated=new AppSettings{Hotkey=hotkey.ToString(),OutputFolder=OutputFolderBox.Text.Trim(),CountdownSeconds=CountdownBox.SelectedItem is int c?c:3,DefaultFormat=FormatBox.SelectedItem is OutputFormat f?f:OutputFormat.Mp4,AudioMode=AudioModeBox.SelectedItem is AudioMode a?a:AudioMode.Off,StartWithWindows=StartWithWindowsBox.IsChecked==true,HasShownFirstRunTip=_settings.HasShownFirstRunTip,MicrophoneDeviceName=_settings.MicrophoneDeviceName,SystemAudioDeviceName=_settings.SystemAudioDeviceName};updated.Normalize();try{Directory.CreateDirectory(updated.OutputFolder);_store.Save(updated);}catch(Exception ex){MessageBox.Show(ex.Message,"viewport-cap");return;}_saved(updated);DialogResult=true;Close();}
 private void Cancel_Click(object sender,RoutedEventArgs e){DialogResult=false;Close();}
}
